package com.test.magicalhaven.server.config

import com.fasterxml.jackson.module.kotlin.jacksonObjectMapper
import org.springframework.context.annotation.*
import org.springframework.http.converter.HttpMessageConverter
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter
import org.springframework.web.servlet.config.annotation.EnableWebMvc
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer
import org.springframework.context.support.PropertySourcesPlaceholderConfigurer

@Configuration
@EnableWebMvc
@EnableAspectJAutoProxy
@ComponentScan(basePackages = ["com.test.magicalhaven.server", "org.springdoc"])
@PropertySource("classpath:application.properties")
open class AppConfig : WebMvcConfigurer {

    override fun configureMessageConverters(converters: MutableList<HttpMessageConverter<*>>) {
        converters.add(MappingJackson2HttpMessageConverter(jacksonObjectMapper()))
    }

    companion object {
        @JvmStatic
        @Bean
        fun propertySourcesPlaceholderConfigurer() = PropertySourcesPlaceholderConfigurer()
    }

    @Bean
    open fun springDocConfig(): org.springdoc.core.properties.SpringDocConfigProperties {
        return org.springdoc.core.properties.SpringDocConfigProperties()
    }
}

package com.test.magicalhaven.server.mapper
import com.test.magicalhaven.server.dto.CreatureDto import com.test.magicalhaven.server.model.Creature import org.springframework.stereotype.Component
@Component class CreatureDtoMapper { fun toDto(domain: Creature): CreatureDto = CreatureDto( id = domain.id, name = domain.name, species = domain.species, temperament = domain.temperament, dailyExpenses = domain.dailyExpenses, adoptionCost = domain.adoptionCost, magicalAbilities = domain.magicalAbilities, adopted = domain.isAdopted )
fun toDomain(dto: CreatureDto): Creature = Creature( id = dto.id, name = dto.name, species = dto.species, temperament = dto.temperament, dailyExpenses = dto.dailyExpenses, adoptionCost = dto.adoptionCost, magicalAbilities = dto.magicalAbilities, isAdopted = dto.adopted ) }

package com.test.magicalhaven.server.mapper
import com.test.magicalhaven.server.model.Creature import com.test.magicalhaven.server.repository.entity.CreatureEntity import org.springframework.stereotype.Component
@Component class CreatureEntityMapper { fun toDomain(entity: CreatureEntity): Creature = Creature( id = entity.id, name = entity.name, species = entity.species, temperament = entity.temperament, dailyExpenses = entity.dailyExpenses, adoptionCost = entity.adoptionCost, magicalAbilities = entity.magicalAbilities, isAdopted = entity.isAdopted )
fun toEntity(domain: Creature): CreatureEntity = CreatureEntity( id = domain.id, name = domain.name, species = domain.species, temperament = domain.temperament, dailyExpenses = domain.dailyExpenses, adoptionCost = domain.adoptionCost, magicalAbilities = domain.magicalAbilities, isAdopted = domain.isAdopted ) }

package com.test.magicalhaven.server.repository
import com.test.magicalhaven.server.repository.entity.CreatureEntity
interface CreatureRepository { fun getAll(): List<CreatureEntity> fun findById(id: Long): CreatureEntity? fun update(creature: CreatureEntity): CreatureEntity }

package com.test.magicalhaven.server.repository

import com.test.magicalhaven.server.repository.entity.CreatureEntity
import org.springframework.beans.factory.InitializingBean
import org.springframework.beans.factory.annotation.Value
import org.springframework.core.io.ResourceLoader
import org.springframework.stereotype.Repository

@Repository
class CsvCreatureRepository(
    private val resourceLoader: ResourceLoader,
    @param:Value("\${app.data.csv-path}") private val csvPath: String
) : CreatureRepository, InitializingBean {

    private val creatures = mutableListOf<CreatureEntity>()

    override fun afterPropertiesSet() {
        loadData()
    }

    override fun getAll(): List<CreatureEntity> = creatures.toList()

    override fun findById(id: Long): CreatureEntity? = creatures.firstOrNull { it.id == id }

    override fun update(creature: CreatureEntity): CreatureEntity {
        val index = creatures.indexOfFirst { it.id == creature.id }
        if (index >= 0) {
            creatures[index] = creature
        }
        return creature
    }

    private fun loadData() {
        val fullPath = if (csvPath.startsWith("classpath:")) csvPath else "classpath:$csvPath"
        val resource = resourceLoader.getResource(fullPath)

        if (resource.exists()) {
            resource.inputStream.bufferedReader().useLines { lines ->
                lines.drop(1).forEach { line ->
                    if (line.isBlank()) return@forEach
                    val regex = ",(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)".toRegex()
                    val parts = line.split(regex)
                    if (parts.size >= 8) {
                        try {
                            val rawAbilities = parts[6].trim()
                            val cleanAbilities = if (rawAbilities.startsWith("\"") && rawAbilities.endsWith("\"")) {
                                rawAbilities.substring(1, rawAbilities.length - 1)
                            } else {
                                rawAbilities
                            }

                            creatures.add(
                                CreatureEntity(
                                    id = parts[0].trim().toLong(),
                                    name = parts[1].trim(),
                                    species = parts[2].trim(),
                                    temperament = parts[3].trim(),
                                    dailyExpenses = parts[4].trim().toDouble(),
                                    adoptionCost = parts[5].trim().toDouble(),
                                    magicalAbilities = cleanAbilities.split(",").map { it.trim() },
                                    isAdopted = parts[7].trim().toBoolean()
                                )
                            )
                        } catch (e: Exception) {
                            println("Error parsing CSV line: $line. Error: ${e.message}")
                        }
                    }
                }
            }
            println("Successfully loaded ${creatures.size} creatures from $fullPath")
        } else {
            println("CRITICAL ERROR: CSV resource not found at $fullPath")
        }
    }
}

package com.test.magicalhaven.server.repository.entity

data class CreatureEntity(
    val id: Long,
    var name: String,
    var species: String,
    var temperament: String,
    var dailyExpenses: Double,
    var adoptionCost: Double,
    var magicalAbilities: List<String>,
    var isAdopted: Boolean
)

package com.test.magicalhaven.server.service

import com.test.magicalhaven.server.model.Creature
import org.springframework.beans.factory.InitializingBean
import org.springframework.beans.factory.annotation.Value
import org.springframework.core.io.ResourceLoader
import org.springframework.stereotype.Service

@Service
class CreatureService(
    private val resourceLoader: ResourceLoader,
    @Value("\${app.data.csv-path}") private val csvPath: String
) : InitializingBean {
    private val creatures = mutableListOf<Creature>()

    override fun afterPropertiesSet() {
        loadData()
    }

    private fun loadData() {
        val fullPath = if (csvPath.startsWith("classpath:")) csvPath else "classpath:$csvPath"
        val resource = resourceLoader.getResource(fullPath)

        if (resource.exists()) {
            resource.inputStream.bufferedReader().useLines { lines ->
                lines.drop(1).forEach { line ->
                    if (line.isBlank()) return@forEach
                    val regex = ",(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)".toRegex()
                    val parts = line.split(regex)
                    if (parts.size >= 8) {
                        try {
                            val rawAbilities = parts[6].trim()
                            val cleanAbilities = if (rawAbilities.startsWith("\"") && rawAbilities.endsWith("\"")) {
                                rawAbilities.substring(1, rawAbilities.length - 1)
                            } else {
                                rawAbilities
                            }

                            creatures.add(
                                Creature(
                                    id = parts[0].trim().toLong(),
                                    name = parts[1].trim(),
                                    species = parts[2].trim(),
                                    temperament = parts[3].trim(),
                                    dailyExpenses = parts[4].trim().toDouble(),
                                    adoptionCost = parts[5].trim().toDouble(),
                                    magicalAbilities = cleanAbilities.split(",").map { it.trim() },
                                    isAdopted = parts[7].trim().toBoolean()
                                )
                            )
                        } catch (e: Exception) {
                            println("Error parsing CSV line: $line. Error: ${e.message}")
                        }
                    }
                }
            }
            println("Successfully loaded ${creatures.size} creatures from $fullPath")
        } else {
            println("CRITICAL ERROR: CSV resource not found at $fullPath")
        }
    }

    fun getAllCreatures(): List<Creature> = creatures.toList()

    fun getAvailableCreatures(): List<Creature> = creatures.filter { !it.isAdopted }

    fun adoptCreature(id: Long): Creature? {
        val creature = creatures.find { it.id == id && !it.isAdopted }
        if (creature != null) {
            creature.isAdopted = true
        }
        return creature
    }
}

package com.test.magicalhaven.server.service

import com.test.magicalhaven.server.mapper.CreatureEntityMapper
import com.test.magicalhaven.server.model.Creature
import com.test.magicalhaven.server.repository.CreatureRepository
import org.springframework.stereotype.Service

@Service
class CreatureService(
    private val creatureRepository: CreatureRepository,
    private val creatureEntityMapper: CreatureEntityMapper
) {
    fun getAllCreatures(): List<Creature> = creatureRepository.getAll()
        .map(creatureEntityMapper::toDomain)

    fun getAvailableCreatures(): List<Creature> = creatureRepository.getAll()
        .filter { !it.isAdopted }
        .map(creatureEntityMapper::toDomain)

    fun adoptCreature(id: Long): Creature? {
        val entity = creatureRepository.findById(id)
        if (entity != null && !entity.isAdopted) {
            entity.isAdopted = true
            creatureRepository.update(entity)
            return creatureEntityMapper.toDomain(entity)
        }
        return null
    }
}
